// @FIGURE_CODE_BEGIN
/* ────────── model ────────── */
const RS_A = 1.0, RS_B = 8.4, RS_W = Math.PI / 3.5;
function curveF(x) { return 2.4 + 1.4 * Math.cos(RS_W * (x - 3.5)); }
const RS_XMIN = -0.95, RS_XMAX = 9.95, RS_YMAX = 4.5, RS_CX0 = 0.35, RS_CX1 = 9.45;
const RS_WORLDW = RS_XMAX - RS_XMIN, RS_WORLDH = RS_YMAX;
const RS_CURVE = '#29ABE2', RS_FILL = '#CCE5F0', RS_GHOST = 'rgba(204,229,240,0.62)';
const RS_EXACT = integrateSimpson(curveF, RS_A, RS_B, 800);
const RS_RULENAME = { min: 'inscribed (min)', left: 'left endpoint', mid: 'midpoint', right: 'right endpoint' };
const RS_state = { single: false, n: 6, rule: 'left', focus: null };
let RS_zones = [];

function rsHeight(xL, xR, rule) {
  if (rule === 'left') return curveF(xL);
  if (rule === 'right') return curveF(xR);
  if (rule === 'mid') return curveF((xL + xR) / 2);
  let m = Infinity;
  for (let k = 0; k <= 32; k++) m = Math.min(m, curveF(xL + (xR - xL) * k / 32));
  return m;
}
function rsSum(n, rule) {
  const dx = (RS_B - RS_A) / n; let s = 0;
  for (let i = 0; i < n; i++) s += rsHeight(RS_A + i * dx, RS_A + (i + 1) * dx, rule) * dx;
  return s;
}
function rsFineN() { return Math.min(100, Math.max(4, RS_state.n * 4)); }
function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

/* ────────── canvas helpers ────────── */
function rsArrow(ctx, x, y, dx, dy, size) {
  const px = -dy, py = dx;
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x - dx * size + px * size * 0.34, y - dy * size + py * size * 0.34);
  ctx.lineTo(x - dx * size - px * size * 0.34, y - dy * size - py * size * 0.34);
  ctx.closePath();
  ctx.fillStyle = '#000';
  ctx.fill();
}
function rsLabel(ctx, txt, x, y, font, align, color, halo) {
  ctx.font = font; ctx.textAlign = align || 'center'; ctx.textBaseline = 'alphabetic';
  if (halo !== false) {
    ctx.lineJoin = 'round'; ctx.lineWidth = Math.max(2, parseFloat(font) * 0.24);
    ctx.strokeStyle = '#fff'; ctx.strokeText(txt, x, y);
  }
  ctx.fillStyle = color || '#000';
  ctx.fillText(txt, x, y);
}
function rsRoundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

/* ────────── one panel (uniform-scale, landscape letterbox) ────────── */
function rsDrawPanel(ctx, box, cfg) {
  const padX = box.w * 0.035, padT = box.h * 0.03, padB = box.h * 0.03;
  const availW = box.w - 2 * padX, availH = box.h - padT - padB;
  if (availW < 40 || availH < 30) return;

  /* vertical budget measured in world units so the drawing keeps its
     natural landscape aspect at any container size */
  const labelUnits = 0.95;                                   // room for a / b under the axis
  const bottomUnits = cfg.caption ? 1.05 : (cfg.readout ? 1.55 : 0.25);
  const totalUnits = RS_WORLDH + labelUnits + bottomUnits;

  const k = Math.min(availW / RS_WORLDW, availH / totalUnits);
  if (k < 3) return;
  const blockH = k * totalUnits, blockW = k * RS_WORLDW;
  const top = box.y + padT + (availH - blockH) / 2;
  const Lx = box.x + (box.w - blockW) / 2;
  const y0 = top + k * RS_WORLDH;
  const X = wx => Lx + (wx - RS_XMIN) * k;
  const Y = wy => y0 - wy * k;

  const fs = clamp(k * 0.5, 8.5, 22);
  const axw = clamp(k * 0.04, 0.8, 2.4);
  const cw = clamp(k * 0.075, 1.4, 5.2);
  const ah = clamp(k * 0.2, 3.5, 12);
  const n = cfg.n, rule = RS_state.rule;
  const R = Lx + blockW;

  /* panel-level hit zone (lowest priority) */
  RS_zones.push({
    x: box.x, y: top, w: box.w, h: blockH,
    tip: cfg.mode === 'exact'
      ? 'Exact region under y = f(x) on [a, b] — area ' + RS_EXACT.toFixed(3)
      : n + ' rectangles (' + RS_RULENAME[rule] + ') — sum ' + rsSum(n, rule).toFixed(3) + ' vs exact ' + RS_EXACT.toFixed(3),
    title: cfg.mode === 'exact' ? 'The area we want' : 'Approximating with rectangles',
    body: cfg.mode === 'exact'
      ? 'This region is bounded above by the curve y = f(x), below by the x-axis, and on the sides by x = a and x = b. Because its top is curved, no elementary area formula applies, so we approximate it with shapes we can measure.'
      : 'Each subinterval carries one rectangle of width Δx = (b − a)/n and a height read off the curve, so its area is exactly height × Δx. Their total is a Riemann sum; the white or tinted slivers show what the rectangles miss.'
  });

  if (cfg.focused) {
    ctx.save();
    rsRoundRect(ctx, box.x + 2, top - k * 0.25, box.w - 4, blockH + k * 0.4, 8);
    ctx.fillStyle = 'rgba(41,171,226,0.06)'; ctx.fill();
    ctx.strokeStyle = 'rgba(41,171,226,0.5)';
    ctx.lineWidth = clamp(k * 0.02, 1, 2.5);
    ctx.stroke();
    ctx.restore();
  }

  /* exact region / ghost */
  if (cfg.mode === 'exact' || cfg.ghost) {
    ctx.beginPath();
    ctx.moveTo(X(RS_A), y0);
    for (let i = 0; i <= 220; i++) { const t = RS_A + (RS_B - RS_A) * i / 220; ctx.lineTo(X(t), Y(curveF(t))); }
    ctx.lineTo(X(RS_B), y0);
    ctx.closePath();
    ctx.fillStyle = (cfg.mode === 'exact') ? RS_FILL : RS_GHOST;
    ctx.fill();
  }

  /* rectangles */
  if (cfg.mode !== 'exact') {
    const dx = (RS_B - RS_A) / n, pw = dx * k;
    const sum = rsSum(n, rule);
    const relErr = Math.abs(RS_EXACT - sum) / RS_EXACT;
    const warmA = Math.min(0.32, relErr * 1.6);
    let thin = clamp(k * 0.02, 0.35, 1.3);
    if (pw < 9) thin = Math.max(0.28, thin * 0.62);
    for (let i = 0; i < n; i++) {
      const xL = RS_A + i * dx, xR = xL + dx, hgt = rsHeight(xL, xR, rule);
      const p0 = X(xL), p1 = X(xR), py = Y(hgt);
      ctx.fillStyle = RS_FILL;
      ctx.fillRect(p0, py, p1 - p0, y0 - py);
      if (cfg.gap && warmA > 0.02) {
        ctx.beginPath();
        ctx.moveTo(p0, py);
        const m = Math.max(4, Math.ceil(pw / 2));
        for (let q = 0; q <= m; q++) { const t = xL + dx * q / m; ctx.lineTo(X(t), Y(curveF(t))); }
        ctx.lineTo(p1, py);
        ctx.closePath();
        ctx.fillStyle = 'rgba(243,146,45,' + warmA.toFixed(3) + ')';
        ctx.fill();
      }
      if (pw > 1.6) {
        ctx.strokeStyle = '#1a1a1a'; ctx.lineWidth = thin;
        ctx.strokeRect(p0, py, p1 - p0, y0 - py);
      }
      if (pw > 6) {
        RS_zones.push({
          x: p0, y: py, w: p1 - p0, h: y0 - py,
          tip: 'Rectangle ' + (i + 1) + ' of ' + n + ':  Δx = ' + dx.toFixed(3) +
               ',  height = ' + hgt.toFixed(3) + ',  area = ' + (hgt * dx).toFixed(4),
          title: 'One rectangle',
          body: 'Its width is Δx = (b − a)/n = ' + dx.toFixed(3) + ' and its height is the function value ' +
                hgt.toFixed(3) + ' sampled by the ' + RS_RULENAME[rule] + ' rule, so its area is exactly ' +
                (hgt * dx).toFixed(4) + '. Adding all ' + n + ' such areas gives the Riemann sum ' + sum.toFixed(3) + '.'
        });
      }
    }
  }

  /* curve */
  ctx.beginPath();
  for (let i = 0; i <= 280; i++) {
    const t = RS_CX0 + (RS_CX1 - RS_CX0) * i / 280, xx = X(t), yy = Y(curveF(t));
    if (i) ctx.lineTo(xx, yy); else ctx.moveTo(xx, yy);
  }
  ctx.strokeStyle = RS_CURVE; ctx.lineWidth = cw; ctx.lineJoin = 'round'; ctx.lineCap = 'round';
  ctx.stroke();

  /* axes */
  ctx.strokeStyle = '#000'; ctx.lineWidth = axw; ctx.lineCap = 'butt';
  const xEnd = X(RS_XMAX);
  ctx.beginPath(); ctx.moveTo(X(RS_XMIN), y0); ctx.lineTo(xEnd, y0); ctx.stroke();
  rsArrow(ctx, xEnd, y0, 1, 0, ah);
  const yTop = Y(RS_YMAX), yBot = y0 + k * 0.4;
  ctx.beginPath(); ctx.moveTo(X(0), yBot); ctx.lineTo(X(0), yTop); ctx.stroke();
  rsArrow(ctx, X(0), yTop, 0, -1, ah);

  /* endpoint segments */
  ctx.lineWidth = clamp(k * 0.022, 0.6, 1.5); ctx.strokeStyle = '#000';
  [RS_A, RS_B].forEach(v => {
    ctx.beginPath(); ctx.moveTo(X(v), y0); ctx.lineTo(X(v), Y(curveF(v))); ctx.stroke();
  });

  /* labels */
  const serif = 'italic ' + fs.toFixed(1) + 'px Georgia, "Times New Roman", serif';
  rsLabel(ctx, 'y', X(0) + fs * 0.5, yTop + fs * 1.05, serif, 'left', '#000');
  rsLabel(ctx, 'x', xEnd - ah * 1.35, y0 - fs * 0.45, serif, 'right', '#000');
  rsLabel(ctx, 'a', X(RS_A), y0 + fs * 1.3, serif, 'center', '#000');
  rsLabel(ctx, 'b', X(RS_B), y0 + fs * 1.3, serif, 'center', '#000');
  if (cfg.caption) {
    rsLabel(ctx, cfg.caption, box.x + box.w / 2, y0 + k * (labelUnits + 0.72),
      'italic ' + clamp(fs * 1.05, 9, 22).toFixed(1) + 'px Georgia, serif', 'center', '#000');
  }

  /* single-panel extras: readout + legend */
  if (cfg.readout) {
    const sum = rsSum(n, rule), err = RS_EXACT - sum, dx = (RS_B - RS_A) / n;
    const lines = [
      'n = ' + n + '        Δx = ' + dx.toFixed(4),
      'Riemann sum = ' + sum.toFixed(3),
      'exact area  = ' + RS_EXACT.toFixed(3),
      'error       = ' + err.toFixed(3) + '  (' + (100 * Math.abs(err) / RS_EXACT).toFixed(2) + '%)',
      'L ' + rsSum(n, 'left').toFixed(2) + '  M ' + rsSum(n, 'mid').toFixed(2) + '  R ' + rsSum(n, 'right').toFixed(2)
    ];
    const f2 = clamp(fs * 0.62, 8.5, 13);
    ctx.font = f2.toFixed(1) + 'px ui-monospace, Consolas, monospace';
    let wmax = 0;
    lines.forEach(l => { wmax = Math.max(wmax, ctx.measureText(l).width); });
    const pad = f2 * 0.65, lh = f2 * 1.42;
    const bw = wmax + pad * 2, bh = lines.length * lh + pad * 1.2;
    const bx = Math.min(X(0.4), R - bw - 4), by = yTop + f2 * 0.3;
    if (bw < blockW * 0.7 && bh < k * RS_WORLDH * 0.75) {
      ctx.save();
      rsRoundRect(ctx, bx, by, bw, bh, f2 * 0.45);
      ctx.fillStyle = 'rgba(255,255,255,0.90)'; ctx.fill();
      ctx.strokeStyle = '#c9d6dd'; ctx.lineWidth = 1; ctx.stroke();
      ctx.restore();
      ctx.textAlign = 'left';
      lines.forEach((l, i) => {
        ctx.font = ((i === 4 ? f2 * 0.92 : f2)).toFixed(1) + 'px ui-monospace, Consolas, monospace';
        ctx.fillStyle = (i === 3) ? '#b45309' : (i === 4 ? '#55636b' : '#20303a');
        ctx.fillText(l, bx + pad, by + pad * 0.8 + lh * (i + 0.78));
      });
    }

    /* legend directly under the axis labels */
    const f3 = clamp(fs * 0.58, 8, 12.5);
    const items = [
      { c: RS_FILL, b: false, t: 'exact region' },
      { c: RS_FILL, b: true, t: 'rectangles' },
      { c: 'rgba(243,146,45,0.33)', b: false, t: 'area missed' }
    ];
    ctx.font = f3.toFixed(1) + 'px sans-serif';
    const sw = f3 * 1.05, gapI = f3 * 1.5;
    let total = 0;
    items.forEach(it => { total += sw + f3 * 0.42 + ctx.measureText(it.t).width + gapI; });
    total -= gapI;
    if (total < box.w * 0.96) {
      let lx = box.x + box.w / 2 - total / 2;
      const lyc = y0 + k * (labelUnits + 0.85);
      items.forEach(it => {
        ctx.fillStyle = it.c; ctx.fillRect(lx, lyc - sw * 0.85, sw, sw);
        if (it.b) { ctx.strokeStyle = '#1a1a1a'; ctx.lineWidth = 0.8; ctx.strokeRect(lx, lyc - sw * 0.85, sw, sw); }
        ctx.fillStyle = '#3a4a52'; ctx.textAlign = 'left';
        ctx.fillText(it.t, lx + sw + f3 * 0.42, lyc);
        lx += sw + f3 * 0.42 + ctx.measureText(it.t).width + gapI;
      });
