}

/* ────────── whole figure ────────── */
function rsDrawAll(ctx, area) {
  RS_zones = [];
  const W = area.right - area.left, H = area.bottom - area.top;
  if (W < 20 || H < 20) return;
  if (RS_state.single) {
    rsDrawPanel(ctx, { x: area.left, y: area.top, w: W, h: H },
      { mode: 'rects', n: RS_state.n, ghost: true, gap: true, readout: true });
  } else {
    const pw = W / 3;
    const cfgs = [
      { mode: 'exact', n: 1, caption: '(a)' },
      { mode: 'rects', n: RS_state.n, caption: '(b)', gap: RS_state.focus === 1 },
      { mode: 'rects', n: rsFineN(), caption: '(c)', gap: RS_state.focus === 2 }
    ];
    for (let i = 0; i < 3; i++) {
      const dim = (RS_state.focus !== null && RS_state.focus !== i);
      ctx.save();
      if (dim) ctx.globalAlpha = 0.42;
      cfgs[i].focused = (RS_state.focus === i);
      rsDrawPanel(ctx, { x: area.left + i * pw, y: area.top, w: pw, h: H }, cfgs[i]);
      ctx.restore();
    }
  }
}

/* ────────── readout panel text ────────── */
function rsUpdateReadout() {
  const el = document.getElementById('rsReadout');
  if (!el) return;
  if (RS_state.single) {
    const n = RS_state.n, s = rsSum(n, RS_state.rule), e = RS_EXACT - s;
    el.textContent =
      'rule : ' + RS_RULENAME[RS_state.rule] + '\n' +
      'n    = ' + n + '   Δx = ' + ((RS_B - RS_A) / n).toFixed(4) + '\n' +
      'sum  = ' + s.toFixed(3) + '\n' +
      'exact= ' + RS_EXACT.toFixed(3) + '\n' +
      'error= ' + e.toFixed(3) + ' (' + (100 * Math.abs(e) / RS_EXACT).toFixed(2) + '%)\n' +
      'L ' + rsSum(n, 'left').toFixed(3) + ' M ' + rsSum(n, 'mid').toFixed(3) + ' R ' + rsSum(n, 'right').toFixed(3);
  } else {
    const nb = RS_state.n, nc = rsFineN();
    const sb = rsSum(nb, RS_state.rule), sc = rsSum(nc, RS_state.rule);
    el.textContent =
      'rule : ' + RS_RULENAME[RS_state.rule] + '\n' +
      '(b) n=' + nb + '  sum = ' + sb.toFixed(3) + '  err ' + (RS_EXACT - sb).toFixed(3) + '\n' +
      '(c) n=' + nc + '  sum = ' + sc.toFixed(3) + '  err ' + (RS_EXACT - sc).toFixed(3) + '\n' +
