// @FIGURE_CODE_BEGIN
/* ────────── model ────────── */
const RS_A = 1.0, RS_B = 8.4, RS_W = Math.PI / 3.5;
function curveF(x) { return 2.4 + 1.4 * Math.cos(RS_W * (x - 3.5)); }
const RS_XMIN = -0.95, RS_XMAX = 9.95, RS_YMAX = 4.5, RS_CX0 = 0.35, RS_CX1 = 9.45;
const RS_WORLDW = RS_XMAX - RS_XMIN;
const RS_CURVE = '#29ABE2', RS_FILL = '#CCE5F0', RS_GHOST = 'rgba(204,229,240,0.60)';
const RS_EXACT = integrateSimpson(curveF, RS_A, RS_B, 800);
const RS_RULENAME = { min: 'inscribed (min)', left: 'left endpoint', mid: 'midpoint', right: 'right endpoint' };
const RS_state = { single: false, n: 5, rule: 'left', focus: null };
let RS_zones = [];

function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
function rsHeight(xL, xR, rule) {
  if (rule === 'left') return curveF(xL);
  if (rule === 'right') return curveF(xR);
  if (rule === 'mid') return curveF((xL + xR) / 2);
  let m = Infinity;
  for (let k = 0; k <= 32; k++) m = Math.min(m, curveF(xL + (xR - xL) * k / 32));
  return m;
}
function rsSum(n, rule) {
  const dx = (RS_B - RS_A) / n; let s = 0;
  for (let i = 0; i < n; i++) s += rsHeight(RS_A + i * dx, RS_A + (i + 1) * dx, rule) * dx;
  return s;
}
function rsFineN() { return Math.min(100, Math.max(4, RS_state.n * 5)); }

/* ────────── canvas helpers ────────── */
function rsArrow(ctx, x, y, dx, dy, size) {
  const px = -dy, py = dx;
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x - dx * size + px * size * 0.34, y - dy * size + py * size * 0.34);
  ctx.lineTo(x - dx * size - px * size * 0.34, y - dy * size - py * size * 0.34);
  ctx.closePath();
  ctx.fillStyle = '#000';
  ctx.fill();
}
function rsLabel(ctx, txt, x, y, font, align, color, haloW) {
  ctx.font = font; ctx.textAlign = align || 'center'; ctx.textBaseline = 'alphabetic';
  ctx.lineJoin = 'round';
  ctx.lineWidth = haloW == null ? 3.2 : haloW;
  ctx.strokeStyle = '#fff';
  ctx.strokeText(txt, x, y);
  ctx.fillStyle = color || '#000';
  ctx.fillText(txt, x, y);
}
function rsRoundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

/* ────────── one panel ────────── */
function rsDrawPanel(ctx, box, cfg) {
  const padX = box.w * 0.02, padT = box.h * 0.02, padB = box.h * 0.02;
  const availW = box.w - 2 * padX, availH = box.h - padT - padB;
  if (availW < 45 || availH < 40) return;

  /* type size first — readability drives the layout, not the other way round */
  const fs = clamp(Math.min(availW * 0.078, availH * 0.085), 9.5, 26);
  const labelBand = fs * 1.6;                       // room for a / b under the axis
  const capBand = cfg.caption ? fs * 2.1 : fs * 0.4;
  const plotH = availH - labelBand - capBand;
  if (plotH < 30) return;

  /* scale: fill the box, but keep the textbook's landscape proportions */
  let kx = availW / RS_WORLDW;
  let ky = plotH / RS_YMAX;
  if (ky > kx * 1.95) ky = kx * 1.95;
  if (ky < kx * 0.70) kx = ky / 0.70;
  const k = Math.sqrt(kx * ky);

  const blockW = kx * RS_WORLDW, blockH = ky * RS_YMAX + labelBand + capBand;
  const top = box.y + padT + Math.max(0, (availH - blockH) / 2);
  const Lx = box.x + (box.w - blockW) / 2;
  const y0 = top + ky * RS_YMAX;
  const X = wx => Lx + (wx - RS_XMIN) * kx;
  const Y = wy => y0 - wy * ky;

  const axw = clamp(k * 0.05, 1, 2.6);
  const cw = clamp(k * 0.095, 1.8, 6);
  const ah = clamp(k * 0.24, 4.5, 14);
  const n = cfg.n, rule = RS_state.rule;
  const R = Lx + blockW;

  /* panel-level hit zone (lowest priority) */
  RS_zones.push({
    x: box.x, y: top, w: box.w, h: blockH,
    tip: cfg.mode === 'exact'
      ? 'Exact region under y = f(x) on [a, b] — area ' + RS_EXACT.toFixed(3)
      : n + ' rectangles (' + RS_RULENAME[rule] + ') — sum ' + rsSum(n, rule).toFixed(3) + ' vs exact ' + RS_EXACT.toFixed(3),
    title: cfg.mode === 'exact' ? 'The area we want' : 'Approximating with rectangles',
    body: cfg.mode === 'exact'
      ? 'This region is bounded above by the curve y = f(x), below by the x-axis, and on the sides by x = a and x = b. Because its top is curved, no elementary area formula applies, so we approximate it with shapes we can measure.'
      : 'Each subinterval carries one rectangle of width Δx = (b − a)/n and a height read off the curve, so its area is exactly height × Δx. Their total is a Riemann sum; the white or tinted slivers show what the rectangles miss.'
  });

  if (cfg.focused) {
    ctx.save();
    rsRoundRect(ctx, box.x + 2, top - fs * 0.4, box.w - 4, blockH + fs * 0.6, 8);
    ctx.fillStyle = 'rgba(41,171,226,0.06)'; ctx.fill();
    ctx.strokeStyle = 'rgba(41,171,226,0.5)';
    ctx.lineWidth = clamp(k * 0.03, 1, 2.5);
    ctx.stroke();
    ctx.restore();
  }

  /* exact region / ghost */
  if (cfg.mode === 'exact' || cfg.ghost) {
    ctx.beginPath();
    ctx.moveTo(X(RS_A), y0);
    for (let i = 0; i <= 240; i++) { const t = RS_A + (RS_B - RS_A) * i / 240; ctx.lineTo(X(t), Y(curveF(t))); }
    ctx.lineTo(X(RS_B), y0);
    ctx.closePath();
    ctx.fillStyle = (cfg.mode === 'exact') ? RS_FILL : RS_GHOST;
    ctx.fill();
  }

  /* rectangles */
  if (cfg.mode !== 'exact') {
    const dx = (RS_B - RS_A) / n, pw = dx * kx;
    const sum = rsSum(n, rule);
    const relErr = Math.abs(RS_EXACT - sum) / RS_EXACT;
    const warmA = Math.min(0.34, relErr * 1.7);
    let thin = clamp(k * 0.026, 0.4, 1.4);
    if (pw < 9) thin = Math.max(0.3, thin * 0.6);
    for (let i = 0; i < n; i++) {
      const xL = RS_A + i * dx, xR = xL + dx, hgt = rsHeight(xL, xR, rule);
      const p0 = X(xL), p1 = X(xR), py = Y(hgt);
      ctx.fillStyle = RS_FILL;
      ctx.fillRect(p0, py, p1 - p0, y0 - py);
      if (cfg.gap && warmA > 0.02) {
        ctx.beginPath();
        ctx.moveTo(p0, py);
        const m = Math.max(4, Math.ceil(pw / 2));
        for (let q = 0; q <= m; q++) { const t = xL + dx * q / m; ctx.lineTo(X(t), Y(curveF(t))); }
        ctx.lineTo(p1, py);
        ctx.closePath();
        ctx.fillStyle = 'rgba(243,146,45,' + warmA.toFixed(3) + ')';
        ctx.fill();
      }
      if (pw > 1.5) {
        ctx.strokeStyle = '#1a1a1a'; ctx.lineWidth = thin;
        ctx.strokeRect(p0, py, p1 - p0, y0 - py);
      }
      if (pw > 6) {
        RS_zones.push({
          x: p0, y: py, w: p1 - p0, h: y0 - py,
          tip: 'Rectangle ' + (i + 1) + ' of ' + n + ':  Δx = ' + dx.toFixed(3) +
               ',  height = ' + hgt.toFixed(3) + ',  area = ' + (hgt * dx).toFixed(4),
          title: 'One rectangle',
          body: 'Its width is Δx = (b − a)/n = ' + dx.toFixed(3) + ' and its height is the function value ' +
                hgt.toFixed(3) + ' sampled by the ' + RS_RULENAME[rule] + ' rule, so its area is exactly ' +
                (hgt * dx).toFixed(4) + '. Adding all ' + n + ' such areas gives the Riemann sum ' + sum.toFixed(3) + '.'
        });
      }
    }
  }

  /* curve */
  ctx.beginPath();
  for (let i = 0; i <= 300; i++) {
    const t = RS_CX0 + (RS_CX1 - RS_CX0) * i / 300, xx = X(t), yy = Y(curveF(t));
    if (i) ctx.lineTo(xx, yy); else ctx.moveTo(xx, yy);
  }
  ctx.strokeStyle = RS_CURVE; ctx.lineWidth = cw; ctx.lineJoin = 'round'; ctx.lineCap = 'round';
  ctx.stroke();

  /* axes */
  ctx.strokeStyle = '#000'; ctx.lineWidth = axw; ctx.lineCap = 'butt';
  const xEnd = X(RS_XMAX);
  ctx.beginPath(); ctx.moveTo(X(RS_XMIN), y0); ctx.lineTo(xEnd, y0); ctx.stroke();
  rsArrow(ctx, xEnd, y0, 1, 0, ah);
  const yTop = Y(RS_YMAX), yBot = y0 + ky * 0.35;
  ctx.beginPath(); ctx.moveTo(X(0), yBot); ctx.lineTo(X(0), yTop); ctx.stroke();
  rsArrow(ctx, X(0), yTop, 0, -1, ah);

  /* endpoint segments */
  ctx.lineWidth = clamp(k * 0.03, 0.7, 1.7); ctx.strokeStyle = '#000';
  [RS_A, RS_B].forEach(v => {
    ctx.beginPath(); ctx.moveTo(X(v), y0); ctx.lineTo(X(v), Y(curveF(v))); ctx.stroke();
  });

  /* labels (drawn last, with white halo) */
  const halo = Math.max(2.4, fs * 0.3);
  const serif = 'italic ' + fs.toFixed(1) + 'px Georgia, "Times New Roman", serif';
  rsLabel(ctx, 'y', X(0) + fs * 0.45, yTop + fs * 1.05, serif, 'left', '#000', halo);
  rsLabel(ctx, 'x', xEnd - ah * 1.45, y0 - fs * 0.5, serif, 'right', '#000', halo);
  rsLabel(ctx, 'a', X(RS_A), y0 + fs * 1.28, serif, 'center', '#000', halo);
  rsLabel(ctx, 'b', X(RS_B), y0 + fs * 1.28, serif, 'center', '#000', halo);
  if (cfg.caption) {
    rsLabel(ctx, cfg.caption, box.x + box.w / 2, y0 + labelBand + fs * 1.25,
      'italic ' + (fs * 1.05).toFixed(1) + 'px Georgia, serif', 'center', '#000', halo);
  }

  /* single-panel readout block */
  if (cfg.readout) {
    const sum = rsSum(n, rule), err = RS_EXACT - sum, dx = (RS_B - RS_A) / n;
    const lines = [
      'n = ' + n + '        Δx = ' + dx.toFixed(4),
      'Riemann sum = ' + sum.toFixed(3),
      'exact area  = ' + RS_EXACT.toFixed(3),
      'error       = ' + err.toFixed(3) + '  (' + (100 * Math.abs(err) / RS_EXACT).toFixed(2) + '%)',
      'L ' + rsSum(n, 'left').toFixed(2) + '  M ' + rsSum(n, 'mid').toFixed(2) + '  R ' + rsSum(n, 'right').toFixed(2)
    ];
    const f2 = clamp(fs * 0.66, 9, 15);
    ctx.font = f2.toFixed(1) + 'px ui-monospace, Consolas, monospace';
    let wmax = 0;
    lines.forEach(l => { wmax = Math.max(wmax, ctx.measureText(l).width); });
    const pad = f2 * 0.7, lh = f2 * 1.45;
    const bw = wmax + pad * 2, bh = lines.length * lh + pad * 1.2;
    const bx = Math.min(X(0.35), R - bw - 4), by = yTop + f2 * 0.25;
    if (bw < blockW * 0.75 && bh < ky * RS_YMAX * 0.8) {
      ctx.save();
      rsRoundRect(ctx, bx, by, bw, bh, f2 * 0.45);
      ctx.fillStyle = 'rgba(255,255,255,0.92)'; ctx.fill();
      ctx.strokeStyle = '#c9d6dd'; ctx.lineWidth = 1; ctx.stroke();
      ctx.restore();
      ctx.textAlign = 'left';
      lines.forEach((l, i) => {
        ctx.font = ((i === 4 ? f2 * 0.92 : f2)).toFixed(1) + 'px ui-monospace, Consolas, monospace';
        ctx.fillStyle = (i === 3) ? '#b45309' : (i === 4 ? '#55636b' : '#20303a');
        ctx.fillText(l, bx + pad, by + pad * 0.8 + lh * (i + 0.78));
      });
    }
  }
}

/* ────────── shared legend strip ────────── */
function rsDrawLegend(ctx, cx, baseY, maxW, f3) {
  const items = [
    { c: RS_FILL, b: false, t: 'exact region' },
    { c: RS_FILL, b: true, t: 'rectangles' },
    { c: 'rgba(243,146,45,0.33)', b: false, t: 'area missed' }
  ];
  ctx.font = f3.toFixed(1) + 'px sans-serif';
  const sw = f3 * 1.05, gapI = f3 * 1.5;
  let total = 0;
  items.forEach(it => { total += sw + f3 * 0.42 + ctx.measureText(it.t).width + gapI; });
  total -= gapI;
  if (total > maxW * 0.96) return;
  let lx = cx - total / 2;
  items.forEach(it => {
    ctx.fillStyle = it.c; ctx.fillRect(lx, baseY - sw * 0.85, sw, sw);
    if (it.b) { ctx.strokeStyle = '#1a1a1a'; ctx.lineWidth = 0.9; ctx.strokeRect(lx, baseY - sw * 0.85, sw, sw); }
    ctx.fillStyle = '#3a4a52'; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
    ctx.fillText(it.t, lx + sw + f3 * 0.42, baseY);
    lx += sw + f3 * 0.42 + ctx.measureText(it.t).width + gapI;
  });
}

/* ────────── whole figure ────────── */
function rsDrawAll(ctx, area) {
  RS_zones = [];
  const W = area.right - area.left, H = area.bottom - area.top;
  if (W < 20 || H < 20) return;

  const legFs = clamp(Math.min(W * 0.022, H * 0.032), 9, 14);
  const legendH = (H > 150 && W > 230) ? legFs * 2.5 : 0;
  const panelsH = H - legendH;

  if (RS_state.single) {
    rsDrawPanel(ctx, { x: area.left, y: area.top, w: W, h: panelsH },
      { mode: 'rects', n: RS_state.n, ghost: true, gap: true, readout: true });
  } else {
    const pw = W / 3;
    const cfgs = [
      { mode: 'exact', n: 1, caption: '(a)' },
      { mode: 'rects', n: RS_state.n, caption: '(b)', gap: RS_state.focus === 1 },
      { mode: 'rects', n: rsFineN(), caption: '(c)', gap: RS_state.focus === 2 }
    ];
    for (let i = 0; i < 3; i++) {
      const dim = (RS_state.focus !== null && RS_state.focus !== i);
      ctx.save();
      if (dim) ctx.globalAlpha = 0.40;
      cfgs[i].focused = (RS_state.focus === i);
      rsDrawPanel(ctx, { x: area.left + i * pw, y: area.top, w: pw, h: panelsH }, cfgs[i]);
      ctx.restore();
    }
  }
  if (legendH) rsDrawLegend(ctx, area.left + W / 2, area.bottom - legendH * 0.38, W, legFs);
}

/* ────────── readout panel text ────────── */
function rsUpdateReadout() {
  const el = document.getElementById('rsReadout');
  if (!el) return;
  if (RS_state.single) {
    const n = RS_state.n, s = rsSum(n, RS_state.rule), e = RS_EXACT - s;
    el.textContent =
      'rule : ' + RS_RULENAME[RS_state.rule] + '\n' +
      'n    = ' + n + '   Δx = ' + ((RS_B - RS_A) / n).toFixed(4) + '\n' +
      'sum  = ' + s.toFixed(3) + '\n' +
      'exact= ' + RS_EXACT.toFixed(3) + '\n' +
      'error= ' + e.toFixed(3) + ' (' + (100 * Math.abs(e) / RS_EXACT).toFixed(2) + '%)\n' +
      'L ' + rsSum(n, 'left').toFixed(3) + ' M ' + rsSum(n, 'mid').toFixed(3) + ' R ' + rsSum(n, 'right').toFixed(3);
  } else {
    const nb = RS_state.n, nc = rsFineN();
    const sb = rsSum(nb, RS_state.rule), sc = rsSum(nc, RS_state.rule);
    el.textContent =
      'rule : ' + RS_RULENAME[RS_state.rule] + '\n' +
      '(b) n=' + nb + '  sum = ' + sb.toFixed(3) + '  err ' + (RS_EXACT - sb).toFixed(3) + '\n' +
      '(c) n=' + nc + '  sum = ' + sc.toFixed(3) + '  err ' + (RS_EXACT - sc).toFixed(3) + '\n' +
      'exact area = ' + RS_EXACT.toFixed(3);
  }
}

/* ────────── control handlers ────────── */
let RS_anim = null, RS_fromAnim = false;
function rsRefresh() { rsUpdateReadout(); if (window.RS_chart) RS_chart.update('none'); }

function update_numRectangles(v) {
  if (!RS_fromAnim && RS_anim) { cancelAnimationFrame(RS_anim); RS_anim = null; }
  RS_state.n = Math.max(1, Math.round(v));
  rsRefresh();
}
function toggle_viewMode(on) { RS_state.single = !!on; if (on) RS_state.focus = null; rsRefresh(); }
function change_sampleRule(v) { RS_state.rule = v; rsRefresh(); }

function rsSetN(n) {
  RS_state.n = n;
  const inp = document.getElementById('numRectanglesInput');
  const out = document.getElementById('numRectanglesVal');
  if (inp) inp.value = n;
  if (out) out.value = n;
}
function rsSetView(on) {
  RS_state.single = on;
  const c = document.getElementById('viewModeInput');
  if (c) c.checked = on;
}
function rsSetRule(r) {
  RS_state.rule = r;
  const sel = document.getElementById('sampleRuleInput');
  if (sel) sel.value = r;
}

function trigger_refineAnimation() {
  if (RS_anim) { cancelAnimationFrame(RS_anim); RS_anim = null; }
  rsSetView(true);
  RS_state.focus = null;
  const t0 = performance.now(), dur = 5000;
  rsSetN(1); rsRefresh();
  const step = t => {
    const u = Math.min(1, (t - t0) / dur);
    RS_fromAnim = true;
    rsSetN(Math.max(1, Math.round(1 + 99 * Math.pow(u, 1.9))));
    RS_fromAnim = false;
    rsRefresh();
    if (u < 1) RS_anim = requestAnimationFrame(step); else RS_anim = null;
  };
  RS_anim = requestAnimationFrame(step);
}

/* ────────── demo steps ────────── */
const RS_STEPS = [
  { title: 'The exact area',
    nar: 'Panel (a): the whole region between the curve and the x-axis from a to b is shaded. This is the quantity we want, but we have no formula for a region with a curved top.',
